import React, { useState } from 'react';

const QuanLyBaiDoXe = () => {
    // Dữ liệu mẫu cho các vị trí đỗ xe
    const [slots] = useState([
        { id: 'P-101', loai: 'Ô tô', trangThai: 'Đã sử dụng', cuDan: 'Phan Vinh' },
        { id: 'P-102', loai: 'Ô tô', trangThai: 'Trống', cuDan: '---' },
        { id: 'M-001', loai: 'Xe máy', trangThai: 'Đã sử dụng', cuDan: 'Nguyễn Văn A' },
        { id: 'M-002', loai: 'Xe máy', trangThai: 'Trống', cuDan: '---' },
    ]);

    return (
        <div style={styles.card}>
            <div style={styles.header}>
                <h2>🅿️ Quản lý bãi đỗ xe</h2>
                <button style={styles.approveBtn}>Phê duyệt đăng ký</button>
            </div>

            <div style={styles.grid}>
                {slots.map((slot) => (
                    <div key={slot.id} style={{
                        ...styles.slotCard, 
                        borderLeft: `10px solid ${slot.trangThai === 'Trống' ? '#4caf50' : '#f44336'}`
                    }}>
                        <div style={styles.slotInfo}>
                            <strong>Vị trí: {slot.id}</strong>
                            <p style={{fontSize: '13px', color: '#666'}}>Loại: {slot.loai}</p>
                            <p style={{fontSize: '12px'}}>Cư dân: {slot.cuDan}</p>
                        </div>
                        <span style={{
                            ...styles.status, 
                            color: slot.trangThai === 'Trống' ? '#2e7d32' : '#d32f2f'
                        }}>
                            {slot.trangThai}
                        </span>
                    </div>
                ))}
            </div>
        </div>
    );
};

const styles = {
    card: { backgroundColor: '#fff', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 10px rgba(0,0,0,0.05)' },
    header: { display: 'flex', justifyContent: 'space-between', marginBottom: '25px' },
    approveBtn: { padding: '10px 15px', backgroundColor: '#1976d2', color: '#fff', border: 'none', borderRadius: '6px', cursor: 'pointer' },
    grid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(250px, 1fr))', gap: '20px' },
    slotCard: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '15px', backgroundColor: '#f9f9f9', borderRadius: '8px' },
    slotInfo: { display: 'flex', flexDirection: 'column', gap: '5px' },
    status: { fontWeight: 'bold', fontSize: '14px' }
};

export default QuanLyBaiDoXe;
